package com.bank.payments;

import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.logging.Logger;

public class InstructionParser {

    private static final Logger log = Logger.getLogger(InstructionParser.class.getName());

    public boolean canSegment(String s, List<String> words) {
        Set<String> dict = new HashSet<>(words);       // O(1) lookups
        int n = s.length();
        boolean[] dp = new boolean[n + 1];
        dp[0] = true;                                  // empty prefix is segmentable
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j < i; j++) {
                if (dp[j] && dict.contains(s.substring(j, i))) {
                    dp[i] = true;                      // reachable boundary + valid word
                    break;
                }
            }
        }
        boolean result = dp[n];
        log.info(() -> "canSegment(" + s + ") = " + result);
        return result;
    }
}
