package com.bank.payments;

import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class WordBreakDemo {

    private static final Logger log = Logger.getLogger(WordBreakDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Instruction Parser (Word Break)");
        InstructionParser parser = new InstructionParser();
        log.info("'paycreditfee' → " + parser.canSegment("paycreditfee",
                List.of("pay", "credit", "fee")));                  // true
        log.info("'payxyz' → " + parser.canSegment("payxyz",
                List.of("pay", "credit", "fee")));                  // false
    }
}
